-- Update Central/South regions UPDATE learning_unit SET metadata_json = '{"tag_code":"V_D_CONFUSION","description":"Lỗi phát âm nhầm lẫn giữa V và D phổ biến ở miền Nam và Trung","regions":["CENTRAL","SOUTH"]}' WHERE id = '00000000-0000-0000-0002-000000000001';
